<script setup>
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import api from '../api.js'
import NoticeCard from '../components/NoticeCard.vue'
import { Megaphone, Search, Users, Pin, List, History, Filter, CalendarDays, BellOff, ChevronRight, ArrowUpRight } from 'lucide-vue-next'
import orientationPhoto from '../assets/images/students-orientation.jpg'
import { useRouter } from 'vue-router'
import { useI18n } from '../composables/useI18n.js'

const { language } = useI18n()
const router = useRouter()
const copy = (en, bn) => language.value === 'bn' ? bn : en

// The labels are for visitors; the values match the backend's category names.
// An empty value means All, so we omit the category query parameter.
const categories = [
  { value: '', en: 'All', bn: 'সব' },
  { value: 'admission', en: 'Admission', bn: 'ভর্তি' },
  { value: 'event', en: 'Event', bn: 'অনুষ্ঠান' },
  { value: 'holiday', en: 'Holiday', bn: 'ছুটি' },
  { value: 'exam', en: 'Exam', bn: 'পরীক্ষা' },
  { value: 'meeting', en: 'Meeting', bn: 'সভা' },
  { value: 'general', en: 'General', bn: 'সাধারণ' },
]
const category = ref('')
const page = ref(1)
const totalPages = ref(1)
const notices = ref([])
const loading = ref(true)
const error = ref(false)
let controller

async function loadNotices() {
  // Quick category changes cancel older requests, keeping results in sync with
  // the selected button even if the network returns responses out of order.
  controller?.abort()
  const request = new AbortController()
  controller = request
  loading.value = true
  error.value = false

  try {
    // Filtering and pagination happen on the backend, 20 notices at a time.
    // api.js supplies the base URL; Axios builds the category query string.
    const response = await api.get('/notices', {
      params: { page: page.value, limit: 20, ...(category.value ? { category: category.value } : {}) },
      signal: request.signal,
      timeout: 15000,
    })
    if (request.signal.aborted) return
    // The actual response contains both the notices and pagination information.
    const data = response.data
    if (!Array.isArray(data?.notices) || !Number.isInteger(data.pagination?.totalPages) || data.pagination.totalPages < 0) {
      throw new Error('Expected notices and pagination')
    }
    notices.value = data.notices
    totalPages.value = Math.max(1, data.pagination.totalPages)
  } catch {
    // Cancellation during navigation or filtering should not display an error.
    if (!request.signal.aborted) error.value = true
  } finally {
    if (!request.signal.aborted) loading.value = false
  }
}

// Start a new category on page 1. Batched watching avoids duplicate requests
// when the category and page change together.
watch(category, () => { page.value = 1 }, { flush: 'sync' })
watch([category, page], loadNotices, { immediate: true })
onBeforeUnmount(() => controller?.abort())

// Map API fields to the original layout's display names. Categories still fetch
// from the backend; search narrows the currently loaded page only.
const audience = computed({ get: () => category.value, set: value => { category.value = value } })
const audiences = computed(() => categories.map(item => ({
  id: item.value, label: copy(item.en, item.bn), sidebar: copy(item.en, item.bn), icon: Users,
})))
const query = ref('')
const filtered = computed(() => loading.value || error.value ? [] : notices.value
  .filter(item => (item.title + ' ' + item.content).toLowerCase().includes(query.value.trim().toLowerCase()))
  .map(item => ({ ...item, id: item._id, published: item.publishDate,
    pinned: item.isImportant === true, audience: categoryName(item.category) })))
const pinned = computed(() => filtered.value.filter(item => item.pinned))
const regular = computed(() => filtered.value.filter(item => !item.pinned))
const recent = computed(() => filtered.value.slice(0, 5))
const isFiltered = computed(() => !!query.value.trim() || !!category.value)
function categoryName(value) {
  const item = categories.find(item => item.value === value)
  return item ? copy(item.en, item.bn) : copy('Notice', 'নোটিশ')
}
function noticeDate(value) {
  if (typeof value !== 'string' || !value.trim()) return null
  const date = new Date(/^\d{4}-\d{2}-\d{2}$/.test(value) ? value + 'T12:00:00' : value)
  return Number.isNaN(date.getTime()) ? null : date
}
function formatDate(value) {
  const date = noticeDate(value)
  return date ? new Intl.DateTimeFormat(language.value === 'bn' ? 'bn-BD' : 'en-GB', { day: 'numeric', month: 'short', year: 'numeric' }).format(date) : copy('Date unavailable', 'তারিখ পাওয়া যায়নি')
}
function datePart(value, part) {
  const date = noticeDate(value)
  return date ? new Intl.DateTimeFormat(language.value === 'bn' ? 'bn-BD' : 'en-GB', { [part]: part === 'day' ? '2-digit' : 'short' }).format(date) : '—'
}
function resetFilters() { query.value = ''; category.value = '' }
function openNotice(item) { router.push({ name: 'notice-detail', params: { id: item._id } }) }
</script>

